{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Ketoprofen, an acidic aromatic ketone with a carboxylic acid, has approximately 90% absolute oral bioavailability in humans; its high F supports the similarly acidic, lipophilic 4-hydroxycoumarin query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Baclofen absolute oral bioavailability was 81.2% in healthy volunteers, showing that even a zwitterionic amino acid can exceed the 20% threshold; supports high F for a small oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Felbamate has >90% absolute oral bioavailability in humans, demonstrating that a neutral, moderately polar small molecule can be essentially completely absorbed; supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Diflunisal, a salicylate with a carboxylic acid and aromatic rings, had 89.5% absolute bioavailability, supporting high F for the acidic aromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Modafinil oral bioavailability is at least 40–65% in humans, still well above the 20% threshold, supporting high classification despite incomplete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Cromolyn has <1% systemic bioavailability after oral administration, but its multiple carboxylates and very low permeability make it structurally distant from the lipophilic warfarin-like query; this contradictory low-F evidence has low transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C36"],
      "claim": "Baicalein has low oral bioavailability, but as a polyphenolic flavone with poor solubility/stability it is not representative of the 4-hydroxycoumarin query; low transferability limits its contradictory weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a warfarin-like 4-hydroxycoumarin with a phenyl ketone side chain: a small, lipophilic, weakly acidic molecule with no obvious permeability liabilities. Multiple structurally diverse oral drugs with high absolute bioavailability (ketoprofen, baclofen, felbamate, diflunisal, modafinil) support F ≥ 20%, while the low-F examples (cromolyn, baicalein) are much more polar/polyphenolic and poorly transferable. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule in the evidence set.",
    "All retrieved analogues have low Morgan similarity (~0.25), limiting quantitative transferability.",
    "No human absolute oral bioavailability data for warfarin itself are included in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

